import { cva } from 'class-variance-authority';
import {
  Children,
  Fragment,
  isValidElement,
  useEffect,
  useId,
  useMemo,
  type ReactElement,
  type ReactNode,
} from 'react';
import { cn } from '@/utils';
import { FEEDBACK_ICON_TABLER } from '@/utils/feedback-tones';
import { Icon } from '../Icon';
import type { IconName } from '../Icon';
import type { BannerProps, BannerTone } from './Banner.types';

/**
 * The banner surface - the same tint and glyph Toast wears, with no edge.
 *
 * Pranjal, 2026-09-28: "in banner we will remove the borders". The tint alone
 * marks the banner out; an outline around it was one line too many inside a
 * form card. Om Vekariya's rule still holds: only the icon and the tint carry
 * the tone. The words stay one colour in every tone, so a danger banner is not
 * also harder to read than an info one.
 *
 * No shadow, and that is the difference you can see. A toast is lifted off the
 * page because it arrived from somewhere else; a banner is part of the layout
 * and sits flat in it.
 */
export const bannerVariants = cva(['mdt-flex mdt-w-full mdt-text-sm mdt-leading-normal'], {
  variants: {
    tone: {
      info: 'mdt-bg-feedback-info-bg',
      warning: 'mdt-bg-feedback-warning-bg',
      danger: 'mdt-bg-feedback-danger-bg',
      success: 'mdt-bg-feedback-success-bg',
      ai: 'mdt-bg-feedback-ai-bg',
      neutral: 'mdt-bg-feedback-neutral-bg',
    },
    placement: {
      inline: 'mdt-gap-2.5 mdt-rounded-lg mdt-py-3 mdt-pl-3.5 mdt-pr-3',
      // Edge to edge: no rounding, because there is nothing beside it to be
      // rounded against. A touch more room at the sides, since the banner is
      // now as wide as the view.
      page: 'mdt-gap-2.5 mdt-rounded-none mdt-py-3 mdt-pl-5 mdt-pr-4',
      // THE PAGE'S NOTICE STRIP (ported from the console, Pranjal 2026-10-28: organizations/Strip.jsx +
      // strip.css, the Collector Fleet and Organization detail notices). Edge to edge across the top of a page,
      // square, a hairline under it in the tone's own border; at least 44 tall; the glyph starts 22 in, where the
      // header band's sidebar-collapse icon starts, and the actions end 24 in, on the header band's inset.
      strip:
        'mdt-box-border mdt-min-h-11 mdt-gap-2.5 mdt-rounded-none mdt-border-0 mdt-border-b mdt-border-solid mdt-py-3 mdt-pl-[22px] mdt-pr-6',
    },
    /**
     * A single row of content - everything centres on it together. Once the
     * banner has a paragraph under the title, or the actions have dropped to
     * their own line, the glyph and the cross belong beside the *first* line
     * rather than halfway down the block.
     *
     * Switched on what the banner is *made of*, never on how it happens to
     * wrap: a title that runs onto a second line by itself still centres,
     * because measuring the wrap would mean the same banner rendered two ways
     * at two window widths. A wrapped title is a sentence; a description is a
     * second thing to read, and that is the line worth drawing.
     */
    stacked: {
      true: 'mdt-items-start',
      false: 'mdt-items-center',
    },
  },
  /* the strip's hairline is its tone's feedback border, the edge the BannerStack bar draws */
  compoundVariants: [
    { placement: 'strip', tone: 'info', class: 'mdt-border-feedback-info-border' },
    { placement: 'strip', tone: 'warning', class: 'mdt-border-feedback-warning-border' },
    { placement: 'strip', tone: 'danger', class: 'mdt-border-feedback-danger-border' },
    { placement: 'strip', tone: 'success', class: 'mdt-border-feedback-success-border' },
    { placement: 'strip', tone: 'ai', class: 'mdt-border-feedback-ai-border' },
    { placement: 'strip', tone: 'neutral', class: 'mdt-border-feedback-neutral-border' },
  ],
  defaultVariants: { tone: 'neutral', placement: 'inline', stacked: false },
});

/** Only the icon carries the tone. */
const ICON_TONE: Record<BannerTone, string> = {
  info: 'mdt-text-feedback-info-icon',
  warning: 'mdt-text-feedback-warning-icon',
  danger: 'mdt-text-feedback-danger-icon',
  success: 'mdt-text-feedback-success-icon',
  ai: 'mdt-text-feedback-ai-icon',
  neutral: 'mdt-text-feedback-neutral-icon',
};

/**
 * The only button a banner carries.
 *
 * A filled button on a tinted surface is a problem with no clean answer. The
 * library's own `secondary` is a blue-grey, so on a cream banner it reads as a
 * chip borrowed from another screen - and the alternative, giving the banner
 * its own tinted grounds, means inventing a look that exists nowhere else in
 * the set. A ghost has no ground to clash, so there is nothing to invent.
 *
 * `link` is allowed alongside it for somewhere genuinely tight. Anything with a
 * fill is warned about.
 */
const ALLOWED_ACTIONS = ['ghost', 'link'];

/** The same glyph per tone that Toast uses - same meaning, same mark: Tabler's outline set, the bulb for info
 * (Pranjal, 2026-09-29: "Do the same for banner component, remove border, use tabler icons and for blue banner use
 * bulb icon from tabler"). */
const TONE_ICON: Record<BannerTone, IconName> = FEEDBACK_ICON_TABLER;

/**
 * The glyph sits in a box exactly one line tall and centres itself inside it.
 *
 * That single rule does both jobs. On a one-line banner the box *is* the line,
 * so the glyph lands on its centre. On a stacked one the row is top-aligned and
 * the box still only covers the first line, so the glyph stays beside it -
 * measured at 0.00px off the first line's centre across a five-line body, in
 * both engines and both themes. Nothing switches between the two.
 */
const GLYPH_BOX = 'mdt-flex mdt-h-[1.5em] mdt-w-4 mdt-shrink-0 mdt-items-center mdt-justify-center';

/**
 * The actions, flattened to one list.
 *
 * `Children.toArray` counts a fragment as one child, and a fragment is exactly
 * how anyone writes two actions - `<><Button/><Button/></>`. Left uncounted,
 * two buttons look like one and stay wedged beside the words. So fragments are
 * opened up before anything is counted.
 */
const flattenActions = (node: ReactNode): ReactNode[] =>
  Children.toArray(node).flatMap((child) =>
    isValidElement(child) && child.type === Fragment
      ? flattenActions((child as ReactElement<{ children?: ReactNode }>).props.children)
      : [child]
  );

/**
 * Warns, in development only, about a filled button in a banner.
 *
 * Two reasons, and they stack. A solid button is the loudest thing on a page
 * and a banner is not the page - put one in a warning and it outranks the Save
 * button the person came for. And any fill has to be a colour: the library's
 * general grounds are blue-greys tuned for the page, and on a cream or a green
 * surface they read as chips borrowed from another screen.
 *
 * The rule is easy to forget and impossible to see in a diff, so it is checked.
 */
const useGhostActions = (flat: readonly ReactNode[]): void => {
  useEffect(() => {
    if (process.env.NODE_ENV === 'production') return;

    // No variant at all is not "no opinion" - `Button` defaults to primary, so
    // an action written the short way is the loudest one there is.
    const variantOf = (child: ReactNode): string | undefined => {
      if (!isValidElement<{ variant?: unknown }>(child)) return undefined;
      const given = child.props.variant;
      return typeof given === 'string' ? given : 'primary';
    };

    const offender = flat
      .map(variantOf)
      .find((variant) => variant !== undefined && !ALLOWED_ACTIONS.includes(variant));

    if (offender !== undefined) {
      console.warn(
        `[Banner] An action is using variant="${offender}". A banner only carries ` +
          'buttons with no ground of their own: a fill has to be a colour, and every ' +
          'colour the library has is tuned for the page rather than for a tinted ' +
          'surface. Use "ghost", or "link" where it is genuinely tight.'
      );
    }
  }, [flat]);
};

/**
 * Banner - a message that sits in the page and stays there.
 *
 * It is about the thing it sits above, it waits for you, and it can carry as
 * many actions as the situation actually needs.
 *
 * **It is not a Toast**, though they share the six tones and the same palette
 * deliberately. A toast floats over the page, arrives on its own and leaves on
 * a timer, so you may not be looking when it appears and it can never hold the
 * only copy of something important. A banner is in the layout, has no timer,
 * and leaves only when the reason for it has gone. *The one-line test: if you
 * would still need the message after a refresh, it is a banner.*
 *
 * It is announced as a region and read in the order it appears, not as a live
 * region that interrupts - which is the other half of the same difference. The
 * region takes its name from the title, so a banner with no title is not a
 * landmark at all.
 *
 * @example
 * ```tsx
 * <Banner
 *   tone="warning"
 *   title="Your trial ends in 3 days"
 *   description="After that, agents keep read-only access until a plan is chosen."
 *   actions={<Button variant="secondary" size="sm">Choose a plan</Button>}
 *   onDismiss={hide}
 * />
 * ```
 */
export const Banner = ({
  tone = 'neutral',
  placement = 'inline',
  title,
  description,
  icon,
  actions,
  actionPlacement: actionPlacementProp,
  onDismiss,
  dismissLabel = 'Dismiss',
  className,
  ...props
}: BannerProps) => {
  const titleId = useId();
  // a strip keeps one row, whatever it carries (the console's Strip always passed "inline")
  const actionPlacement = actionPlacementProp ?? (placement === 'strip' ? 'inline' : 'auto');
  const flat = useMemo(() => flattenActions(actions), [actions]);
  useGhostActions(flat);

  const hasActions = flat.length > 0;

  // One action sits beside the words; two or more go on their own line. Counted
  // rather than measured, so the same banner always renders the same way.
  const below =
    hasActions && (actionPlacement === 'below' || (actionPlacement === 'auto' && flat.length > 1));

  const beside = hasActions && !below;
  const hasTitle = title !== undefined && title !== null && title !== '';
  const stacked =
    below || (description !== undefined && description !== null && description !== '');

  const renderGlyph = (): ReactNode => {
    if (icon === null) return null;
    return (
      <span className={cn(GLYPH_BOX, ICON_TONE[tone])} data-slot="banner-icon" aria-hidden="true">
        {icon ?? <Icon name={TONE_ICON[tone]} size="sm" />}
      </span>
    );
  };

  return (
    <section
      className={cn(bannerVariants({ tone, placement, stacked }), className)}
      data-tone={tone}
      data-slot="banner"
      // A `section` is only a landmark once it has a name, which is exactly the
      // behaviour wanted here - a titled banner joins the landmark list, an
      // untitled one-liner does not clutter it.
      {...(hasTitle ? { 'aria-labelledby': titleId } : {})}
      {...props}
    >
      {renderGlyph()}

      {/* min-w-0 lets a long word wrap instead of forcing the banner wider */}
      <div className="mdt-min-w-0 mdt-flex-1 mdt-text-feedback-text">
        {hasTitle ? (
          <p
            id={titleId}
            className="mdt-font-semibold mdt-text-feedback-title"
            data-slot="banner-title"
          >
            {title}
          </p>
        ) : null}

        {description !== undefined && description !== null && description !== '' ? (
          <p className={cn(hasTitle && 'mdt-mt-0.5')} data-slot="banner-description">
            {description}
          </p>
        ) : null}

        {below ? (
          <div
            className="mdt-mt-2.5 mdt-flex mdt-flex-wrap mdt-items-center mdt-gap-2"
            data-slot="banner-actions"
          >
            {actions}
          </div>
        ) : null}
      </div>

      {beside || onDismiss ? (
        <div
          className={cn(
            'mdt-flex mdt-shrink-0 mdt-items-center mdt-gap-2',
            // Whatever is in here sits on the banner's own centre line, however
            // many lines of text are beside it. A control is not part of the
            // sentence, so pinning it to the first line leaves it stranded in
            // the top corner of a two-line banner.
            //
            // The one exception is a banner whose actions have already dropped
            // below: the cross is then alone in the top corner, above the
            // block it closes, which is exactly where a dismiss belongs.
            below ? 'mdt-h-[1.5em]' : 'mdt-self-center'
          )}
          data-slot="banner-end"
        >
          {beside ? (
            <div className="mdt-flex mdt-items-center mdt-gap-2" data-slot="banner-actions">
              {actions}
            </div>
          ) : null}

          {onDismiss ? (
            <button
              type="button"
              onClick={onDismiss}
              aria-label={dismissLabel}
              data-slot="banner-dismiss"
              // Deliberately outside the tone system, exactly as Toast's is.
              // Only the icon and the tint carry the tone, and a coloured
              // cross would compete with the glyph for the same job. Its hover
              // is the banner's own words at a tenth - so it darkens whatever
              // surface it is on rather than laying a grey patch over it.
              className={cn(
                'mdt-flex mdt-h-7 mdt-w-7 mdt-shrink-0 mdt-items-center mdt-justify-center',
                'mdt-rounded-md mdt-transition-colors',
                'mdt-text-feedback-text/70 hover:mdt-bg-feedback-text/10 hover:mdt-text-feedback-text',
                'focus-visible:mdt-outline-none focus-visible:mdt-ring-2 focus-visible:mdt-ring-ring'
              )}
            >
              <Icon name="tabler-x" size="sm" aria-hidden />
            </button>
          ) : null}
        </div>
      ) : null}
    </section>
  );
};

Banner.displayName = 'Banner';
